import math

training = [
    ("winner claim your free prize", 1), ("free cash now", 1), ("cash prize winner", 1),
    ("urgent claim cash", 1), ("meeting moved to friday", 0), ("homework due friday", 0),
    ("lunch meeting tomorrow", 0), ("see the homework notes", 0),
]


def rule(text):
    return "free money" in text or "free prize" in text


counts = {1: {}, 0: {}}
for text, label in training:
    for word in text.split():
        counts[label][word] = counts[label].get(word, 0) + 1
vocab = set(counts[0]) | set(counts[1])
total = {c: sum(counts[c].values()) + len(vocab) for c in (0, 1)}
weight = {w: math.log((counts[1].get(w, 0) + 1) / total[1]) - math.log((counts[0].get(w, 0) + 1) / total[0]) for w in vocab}

print("learned word weights (positive = spammy):")
ranked = sorted(weight, key=lambda w: (-weight[w], w))      # ties broken alphabetically
for w in ranked[:4] + ranked[-3:]:
    print(f"  {w:9} {weight[w]:+.2f}")


def learned(text):
    return sum(weight.get(w, 0) for w in text.split()) > 0


print()
for email in ["claim your cash prize now", "homework due at the meeting", "free prize inside"]:
    print(f"{email:30} rule: {'spam' if rule(email) else 'ok':4}   learned: {'spam' if learned(email) else 'ok'}")

