memory = {h: label for h, label in train}


def memorizer(h):
    return memory.get(h, 0)                    # unseen input: guess 0


best = max(range(10, 50), key=lambda t: sum((h >= t) == bool(y) for h, y in train))


def threshold_model(h):
    return 1 if h >= best else 0


